package com.pktracker;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class PkTrackerPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(PkTrackerPlugin.class);
		RuneLite.main(args);
	}
}

package com.pktracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(PkTrackerPlugin.CONFIG_GROUP)
public interface PkTrackerConfig extends Config
{
	@ConfigSection(
		name = "Screenshots",
		description = "Kill/death screenshots. For best performance, open the built-in RuneLite 'Screenshot' plugin and turn OFF its 'Screenshot PvP kills' and 'Screenshot deaths' options, so you aren't capturing two screenshots at once.",
		position = 100,
		closedByDefault = false
	)
	String screenshotSection = "screenshotSection";
	@ConfigItem(
		keyName = "lookupOnFightStart",
		name = "Lookup stats on fight start",
		description = "Automatically look up an opponent's hiscore stats when a fight begins",
		position = 0
	)
	default boolean lookupOnFightStart()
	{
		return true;
	}

	@ConfigItem(
		keyName = "statsChatMessage",
		name = "Opponent stats in chat",
		description = "Also print the opponent's combat stats to the chatbox",
		position = 1
	)
	default boolean statsChatMessage()
	{
		return false;
	}

	@ConfigItem(
		keyName = "killChatMessage",
		name = "Kill message in chat",
		description = "Print a message with the loot value when you get a kill",
		position = 2
	)
	default boolean killChatMessage()
	{
		return true;
	}

	@ConfigItem(
		keyName = "pvpDeathsOnly",
		name = "Only count PvP deaths",
		description = "Only count deaths that happen while in combat with another player (ignores PvM deaths)",
		position = 3
	)
	default boolean pvpDeathsOnly()
	{
		return true;
	}

	@Range(min = 10, max = 1000)
	@ConfigItem(
		keyName = "maxHistoryEntries",
		name = "Max history entries",
		description = "Maximum number of kills kept in the persistent loot history",
		position = 4
	)
	default int maxHistoryEntries()
	{
		return 250;
	}

	@ConfigItem(
		keyName = "lookupCooldown",
		name = "Lookup cooldown (seconds)",
		description = "How long before the same opponent will be looked up again",
		position = 5
	)
	default int lookupCooldown()
	{
		return 120;
	}
	@ConfigItem(
		keyName = "rightClickLookup",
		name = "Right-click PK Lookup",
		description = "Adds a 'PK Lookup' option when you right-click a player",
		position = 6
	)
	default boolean rightClickLookup()
	{
		return true;
	}

	@ConfigItem(
		keyName = "damageOverlay",
		name = "Damage overlay",
		description = "Show an on-screen overlay of damage dealt to and taken from your opponent during a fight",
		position = 7
	)
	default boolean damageOverlay()
	{
		return false;
	}

	@Range(min = 5, max = 120)
	@ConfigItem(
		keyName = "damageResetDelay",
		name = "Fight reset delay (s)",
		description = "Seconds of no combat before the damage overlay resets (also clears instantly on entering a safe zone or starting a new fight)",
		position = 8
	)
	default int damageResetDelay()
	{
		return 30;
	}

	@ConfigItem(
		keyName = "sessionOverlay",
		name = "Session stats overlay",
		description = "Show an on-screen overlay with your session kills, deaths, K/D, streak and loot",
		position = 9
	)
	default boolean sessionOverlay()
	{
		return false;
	}

	@ConfigItem(
		keyName = "opponentOverlay",
		name = "Opponent overlay",
		description = "Show an on-screen overlay with the current opponent's stats, BH/LMS ranks, saved note and damage during a fight",
		position = 10
	)
	default boolean opponentOverlay()
	{
		return false;
	}

	@ConfigItem(
		keyName = "killScreenshot",
		name = "Screenshot on kill/death",
		description = "Automatically screenshot the moment you kill an opponent or die, capturing the final hitsplats (game view only, saved to the PK Tracker folder). For best performance, disable the built-in RuneLite Screenshot plugin's 'Screenshot PvP kills' and 'Screenshot deaths' options so you aren't taking two screenshots at once.",
		position = 11,
		section = screenshotSection
	)
	default boolean killScreenshot()
	{
		return false;
	}
}

package com.pktracker;

/**
 * Holds the result of a hiscore lookup for the current fight opponent.
 */
public class OpponentStats
{
	public final String name;
	public final int attack;
	public final int strength;
	public final int defence;
	public final int hitpoints;
	public final int ranged;
	public final int magic;
	public final int prayer;
	public final int combatLevel;

	// Minigame scores (-1 = unranked)
	public final int bhHunter;
	public final int bhRogue;
	public final int lms;

	public OpponentStats(String name, int attack, int strength, int defence,
		int hitpoints, int ranged, int magic, int prayer, int combatLevel,
		int bhHunter, int bhRogue, int lms)
	{
		this.name = name;
		this.attack = attack;
		this.strength = strength;
		this.defence = defence;
		this.hitpoints = hitpoints;
		this.ranged = ranged;
		this.magic = magic;
		this.prayer = prayer;
		this.combatLevel = combatLevel;
		this.bhHunter = bhHunter;
		this.bhRogue = bhRogue;
		this.lms = lms;
	}
}

package com.pktracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Custom-drawn damage overlay: "You" vs "Opponent" damage for the current
 * fight. Styled to match the session and opponent overlays. Visible only
 * while a fight is active.
 */
public class PkDamageOverlay extends Overlay
{
	private static final Color BG = new Color(40, 40, 40, 220);
	private static final Color BORDER = new Color(70, 70, 70);
	private static final Color TEXT = Color.WHITE;
	private static final Color GREEN = new Color(0, 200, 83);
	private static final Color RED = new Color(244, 67, 54);
	private static final Color LIGHT = new Color(170, 170, 170);

	private static final int PAD = 8;
	private static final int WIDTH = 130;
	private static final int ROW_H = 18;

	private final PkTrackerPlugin plugin;
	private final PkTrackerConfig config;

	public PkDamageOverlay(PkTrackerPlugin plugin, PkTrackerConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.damageOverlay() || !plugin.isEngaged())
		{
			return null;
		}

		final int rows = 3; // title + 2 lines
		final int height = PAD * 2 + rows * ROW_H;

		g.setColor(BG);
		g.fillRect(0, 0, WIDTH, height);
		g.setColor(BORDER);
		g.drawRect(0, 0, WIDTH - 1, height - 1);

		final Font font = FontManager.getRunescapeSmallFont();
		g.setFont(font);
		final FontMetrics fm = g.getFontMetrics();

		int y = PAD + ROW_H - 5;

		g.setColor(TEXT);
		g.drawString("Damage", PAD, y);
		y += ROW_H;

		drawRow(g, fm, "You", String.valueOf(plugin.getDamageDealt()), GREEN, y);
		y += ROW_H;
		drawRow(g, fm, "Opponent", String.valueOf(plugin.getDamageTaken()), RED, y);

		return new Dimension(WIDTH, height);
	}

	private void drawRow(Graphics2D g, FontMetrics fm, String label, String value, Color valueColor, int y)
	{
		g.setColor(LIGHT);
		g.drawString(label, PAD, y);
		g.setColor(valueColor);
		int vx = WIDTH - PAD - fm.stringWidth(value);
		g.drawString(value, vx, y);
	}
}

package com.pktracker;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
